:root {
  --navy: #18324a;
  --water: #dff3f2;
  --foam: #ffffff;
  --teal: #167c80;
}

.transit-token {
  display: flex;
  align-items: center;
  gap: 14px;
  width: 440px;
  padding: 16px;
  background: var(--foam);
  border: 2px solid var(--navy);
  border-radius: 14px;
}

.lock-mark {
  display: grid;
  width: 46px;
  height: 46px;
  place-items: center;
  background: var(--water);
  border-radius: 50%;
  font-size: 23px;
}

.token-details {
  flex: 1;
}

.eyebrow {
  margin: 0;
  color: var(--teal);
  font-size: 11px;
  font-weight: 700;
}

h1 {
  margin: 3px 0;
  color: var(--navy);
  font-size: 20px;
}

.time {
  margin: 0;
  color: var(--navy);
  font-size: 14px;
}

button {
  padding: 7px 10px;
  color: var(--foam);
  background: var(--teal);
  border: 0;
  border-radius: 6px;
  font-weight: 700;
}
